package org.humanjourney.core.advancement.client;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.advancements.*;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.resources.ResourceLocation;
import org.humanjourney.core.advancement.*;
/** Mutates only native widget pixel fields and native scroll bounds, never DisplayInfo or progression. */
public final class NativeAdapter {
 private static final class State {final Map<AdvancementWidget,NativePresentation.Point> original=new WeakHashMap<>();NativePresentation.Tab active;boolean drawFailed;}
 private static final Map<AdvancementTab,State> states=new WeakHashMap<>();private static String problem="";
 public static String problem(){return problem;}
 public static void prepare(AdvancementTab tab){try{var data=NativeClient.STATE.view().tabs().stream().filter(t->t.root().equals(tab.getRootNode().holder().id().toString())).findFirst().orElse(null);if(!(tab instanceof NativeTabAccess access))return;if(data==null&&!states.containsKey(tab))return;var state=states.computeIfAbsent(tab,t->new State());if(state.drawFailed)return;var widgets=access.hjWidgets();if(widgets.size()>2048)throw new IllegalStateException("native widget safety limit2048");state.original.keySet().retainAll(widgets.values());for(var w:widgets.values()){if(!(w instanceof NativeWidgetAccess a))throw new IllegalStateException("native widget hook unavailable");state.original.putIfAbsent(w,new NativePresentation.Point(a.hjX(),a.hjY()));}if(data!=null)NativePresentation.textures(data,id->Minecraft.getInstance().getResourceManager().getResource(ResourceLocation.parse(id)).isPresent());apply(tab,state,data);state.active=data;problem="";}catch(RuntimeException|LinkageError error){var state=states.get(tab);if(state!=null)try{apply(tab,state,null);state.active=null;}catch(RuntimeException|LinkageError ignored){}String message="Native advancement presentation disabled; vanilla fallback: "+error.getMessage();if(!message.equals(problem)){problem=message;com.mojang.logging.LogUtils.getLogger().warn("[HJ Core] {}",message);}}}
 private static void apply(AdvancementTab tab,State state,NativePresentation.Tab data){var access=(NativeTabAccess)tab;var positions=new HashMap<String,NativePresentation.Position>();if(data!=null)for(var p:data.positions())positions.put(p.advancement(),p);int minX=Integer.MAX_VALUE,minY=minX,maxX=Integer.MIN_VALUE,maxY=maxX;boolean changed=false;int rootDx=0,rootDy=0;String root=tab.getRootNode().holder().id().toString();for(var e:state.original.entrySet()){var w=(NativeWidgetAccess)e.getKey();var base=e.getValue();var override=w.hjDrawn()?positions.get(w.hjId()):null;int x=override==null?base.x():override.x(),y=override==null?base.y():override.y();if(w.hjId().equals(root)){rootDx=x-w.hjX();rootDy=y-w.hjY();}changed|=x!=w.hjX()||y!=w.hjY();w.hjPosition(x,y);minX=Math.min(minX,x+28);maxX=Math.max(maxX,x+28);minY=Math.min(minY,y+27);maxY=Math.max(maxY,y+27);}if(changed){access.hjBounds(minX,minY,maxX,maxY);access.hjScroll(access.hjScrollX()-rootDx,access.hjScrollY()-rootDy);}}
 public static void restoreAll(){for(var e:states.entrySet())try{apply(e.getKey(),e.getValue(),null);}catch(RuntimeException|LinkageError ignored){}states.clear();problem="";}
 public static void draw(AdvancementTab tab,GuiGraphics g){var state=states.get(tab);if(state==null||state.active==null)return;try{var access=(NativeTabAccess)tab;int sx=(int)Math.floor(access.hjScrollX()),sy=(int)Math.floor(access.hjScrollY());var widgets=new HashMap<String,NativePresentation.Widget>();for(var w:access.hjWidgets().values()){var a=(NativeWidgetAccess)w;widgets.put(a.hjId(),new NativePresentation.Widget(a.hjId(),a.hjParent(),a.hjX(),a.hjY(),a.hjDrawn()));}for(var area:state.active.eras())if(area.members().stream().anyMatch(id->widgets.containsKey(id)&&widgets.get(id).visible()))region(g,area,sx,sy);for(var edge:NativePresentation.drawable(state.active,widgets)){var route=NativePresentation.route(edge,widgets);for(int pass=0;pass<2;pass++)for(int i=1;i<route.size();i++)line(g,route.get(i-1),route.get(i),sx,sy,pass==0?0xFF000000:0xFFFFFFFF,pass==0?3:1);}}catch(RuntimeException|LinkageError error){try{apply(tab,state,null);}catch(RuntimeException|LinkageError ignored){}state.active=null;state.drawFailed=true;String message="Native advancement drawing failed; vanilla retained: "+error.getMessage();if(!message.equals(problem)){problem=message;com.mojang.logging.LogUtils.getLogger().warn("[HJ Core] {}",message);}}}
 private static void region(GuiGraphics g,NativePresentation.Region a,int sx,int sy){int x=sx+a.x(),y=sy+a.y(),left=Math.max(0,x),top=Math.max(0,y),right=Math.min(234,x+a.width()),bottom=Math.min(113,y+a.height());if(left>=right||top>=bottom)return;g.fill(left,top,right,bottom,0xFF000000|a.color());if(a.texture()!=null){var texture=ResourceLocation.parse(a.texture());for(int tx=x+Math.floorDiv(left-x,16)*16;tx<right;tx+=16)for(int ty=y+Math.floorDiv(top-y,16)*16;ty<bottom;ty+=16){int bx=Math.max(left,tx),by=Math.max(top,ty),w=Math.min(right,tx+16)-bx,h=Math.min(bottom,ty+16)-by;g.blit(RenderPipelines.GUI_TEXTURED,texture,bx,by,(float)(bx-tx),(float)(by-ty),w,h,16,16);}}if(a.tint()!=null)g.fill(left,top,right,bottom,0x40000000|a.tint());g.renderOutline(x,y,a.width(),a.height(),0xFF000000|a.border());var font=Minecraft.getInstance().font;String title=font.plainSubstrByWidth(a.title(),Math.max(0,a.width()-8));g.drawString(font,title,x+4,y+4,0xFF000000|a.border(),true);}
 private static void line(GuiGraphics g,NativePresentation.Point a,NativePresentation.Point b,int sx,int sy,int color,int width){double dx=b.x()-a.x(),dy=b.y()-a.y(),length=Math.hypot(dx,dy);if(length<.01)return;int ax=a.x()+sx,ay=a.y()+sy,bx=b.x()+sx,by=b.y()+sy;if(Math.max(ax,bx)<0||Math.min(ax,bx)>234||Math.max(ay,by)<0||Math.min(ay,by)>113)return;var pose=g.pose();pose.pushMatrix();try{pose.translate(ax,ay-width/2f);pose.rotate((float)Math.atan2(dy,dx));pose.scale((float)length,width);g.fill(0,0,1,1,color);}finally{pose.popMatrix();}}
 private NativeAdapter(){}
}
